// Main.java
class Bentuk {
    double luas() {
        return 0;
    }
}

class Persegi extends Bentuk {
    double sisi;

    Persegi(double sisi) {
        this.sisi = sisi;
    }

    @Override
    double luas() {
        return sisi * ____;
    }
}

class Lingkaran extends Bentuk {
    double r;

    Lingkaran(double r) {
        this.r = r;
    }

    @Override
    double luas() {
        return 3.14 * r * ____;
    }
}

public class Main {
    public static void main(String[] args) {
        Bentuk[] daftar = { new Persegi(3), new Lingkaran(2) };
        for (Bentuk b : daftar) {
            System.out.println("Luas: " + b.luas());
        }
    }
}

